"""Generated clone installers. Never edit the committed adapter outputs."""
from __future__ import annotations

import json
import re
from string import Template

from .host_adapters import HOST_ADAPTERS, host_adapter_manifest


_SH = Template(r'''#!/bin/sh
# Generated by omh docs agent-skills; edit the catalog/producer, not this file.
set -eu
fail() { printf '%s\n' "$$*" >&2; exit 1; }
scope=repo
case $$# in
    0) ;;
    1) [ "$$1" = --user ] || fail 'Usage: install.sh [--user]'; scope=user ;;
    *) fail 'Usage: install.sh [--user]' ;;
esac
base=$$(pwd -P)
if [ "$$scope" = user ]; then
    [ -n "$${HOME:-}" ] || fail 'HOME is required for --user'
    base=$$(CDPATH= cd -- "$$HOME" && pwd -P)
    target="$$base/$user_path"
else
    target="$$base/$repo_path"
fi
source="$$(dirname -- "$$0")/../agent-skills"
[ ! -L "$$source" ] || fail 'Symlink source root'
source=$$(CDPATH= cd -- "$$source" && pwd -P)
if command -v sha256sum >/dev/null 2>&1; then
    checksum() { sha256sum "$$@"; }
elif command -v shasum >/dev/null 2>&1; then
    checksum() { shasum -a 256 "$$@"; }
else
    fail 'SHA256 verification requires sha256sum or shasum'
fi
# The receipt is the one inventory: generated beside the pack, pinned by the
# docs gate, and copied verbatim. Its "files" rows are the only 4-space-indented
# "<path>": "<sha256>" lines; a row this misses leaves its file unlisted, which
# the inventory comparison below refuses.
inventory="$$source/$receipt_name"
[ -f "$$inventory" ] || fail 'Missing source inventory'
checksums=$$(sed -n 's/^    "\([^"]*\)": "\([0-9a-f]\{64\}\)",\{0,1\}$$/\2  \1/p' "$$inventory")
[ -n "$$checksums" ] || fail 'Empty source inventory'
paths=$$(printf '%s\n' "$$checksums" | sed 's/^[0-9a-f]*  //')
# Reject extra files and links rather than silently installing an unverified tree.
[ -z "$$(find "$$source" ! -type f ! -type d -print)" ] || fail 'Unsupported source entry (including symlink)'
actual=$$(cd "$$source" && find . -type f ! -path './$receipt_name' -print | LC_ALL=C sort)
expected=$$(printf '%s\n' "$$paths" | while IFS= read -r path; do printf './%s\n' "$$path"; done | LC_ALL=C sort)
[ "$$actual" = "$$expected" ] || fail 'Source file inventory mismatch'
verify() {
    printf '%s\n' "$$checksums" | (cd "$$1" && checksum -c -) >/dev/null || fail 'Skill digest mismatch'
}
verify "$$source"
# Preflight EVERY target before the first write, including the receipt.
# Do not follow destination links.
printf '%s\n' "$$paths" '$receipt_name' | while IFS= read -r path; do
    current="$$target/$$path"
    while [ "$$current" != "$$base" ]; do
        [ ! -L "$$current" ] || fail "Symlink destination: $$current"
        current=$${current%/*}
        [ -n "$$current" ] || current=/
    done
    [ ! -e "$$target/$$path" ] || [ -f "$$target/$$path" ] || fail "Not a file: $$target/$$path"
done
printf '%s\n' "$$paths" | while IFS= read -r path; do
    mkdir -p "$$target/$${path%/*}"
    cp "$$source/$$path" "$$target/$$path"
done
verify "$$target"
cp "$$inventory" "$$target/$receipt_name"
printf 'Installed $host skills in %s\n' "$$target"
printf '%s\n' "$$paths" | sed 's|/.*||' | LC_ALL=C sort -u
''')

_PS1 = Template(r'''# Generated by omh docs agent-skills; edit the catalog/producer, not this file.
param([switch]$$User)
$$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if ($$args.Count) { throw 'Usage: install.ps1 [-User]' }
$$base = (Get-Location).ProviderPath
if ($$User) {
    $$base = $$env:USERPROFILE
    if (-not $$base) { $$base = $$env:HOME }
    if (-not $$base) { throw 'User profile is required for -User' }
    $$target = Join-Path $$base '$user_path'
} else {
    $$target = Join-Path $$base '$repo_path'
}
$$source = Join-Path (Split-Path -Parent $$PSScriptRoot) 'agent-skills'
$$inventory = Join-Path $$source '$receipt_name'
if (-not (Test-Path -LiteralPath $$inventory -PathType Leaf)) { throw 'Missing source inventory' }
$$inventoryPath = (Get-Item -Force -LiteralPath $$inventory).FullName
# The receipt is the one inventory: generated beside the pack, pinned by the
# docs gate, and copied verbatim after every listed file verifies.
$$entries = @((Get-Content -Raw -Encoding UTF8 -LiteralPath $$inventory | ConvertFrom-Json).files.PSObject.Properties |
    ForEach-Object { [PSCustomObject]@{ Path = $$_.Name; Hash = [string]$$_.Value } })
if (-not $$entries.Count) { throw 'Empty source inventory' }
function Assert-NoLink([string]$$Path, [string]$$Boundary) {
    $$current = $$Path
    while ($$current -and $$current -ne $$Boundary) {
        if (Test-Path -LiteralPath $$current) {
            $$item = Get-Item -Force -LiteralPath $$current
            if ($$item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
                throw "Reparse-point path: $$current"
            }
        }
        $$current = Split-Path -Parent $$current
    }
}
Assert-NoLink $$source (Split-Path -Parent $$source)
$$items = @(Get-ChildItem -Force -Recurse -LiteralPath $$source)
foreach ($$item in $$items) {
    if ($$item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
        throw "Reparse-point source: $$($$item.FullName)"
    }
}
$$sourceFiles = @($$items | Where-Object { -not $$_.PSIsContainer -and $$_.FullName -ne $$inventoryPath })
if ($$sourceFiles.Count -ne $$entries.Count) { throw 'Source file inventory mismatch' }
function Assert-Digests([string]$$Root) {
    foreach ($$entry in $$entries) {
        $$path = Join-Path $$Root $$entry.Path
        if (-not (Test-Path -LiteralPath $$path -PathType Leaf)) { throw "Missing skill: $$path" }
        if ((Get-FileHash -LiteralPath $$path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $$entry.Hash) {
            throw "Skill digest mismatch: $$path"
        }
    }
}
Assert-Digests $$source
# Preflight the receipt as well as every copied file before any write.
foreach ($$relative in (@($$entries.Path) + '$receipt_name')) {
    $$path = Join-Path $$target $$relative
    Assert-NoLink $$path $$base
    if ((Test-Path -LiteralPath $$path) -and -not (Test-Path -LiteralPath $$path -PathType Leaf)) {
        throw "Not a file: $$path"
    }
}
foreach ($$entry in $$entries) {
    $$path = Join-Path $$target $$entry.Path
    [IO.Directory]::CreateDirectory((Split-Path -Parent $$path)) | Out-Null
    [IO.File]::Copy((Join-Path $$source $$entry.Path), $$path, $$true)
}
Assert-Digests $$target
[IO.File]::Copy($$inventory, (Join-Path $$target '$receipt_name'), $$true)
Write-Output "Installed $host skills in $$target"
$$skills = [Collections.Generic.SortedSet[string]]::new([StringComparer]::Ordinal)
foreach ($$entry in $$entries) { [void]$$skills.Add($$entry.Path.Split('/')[0]) }
$$skills
''')


def host_adapter_files(files: dict[str, str]) -> dict[str, str]:
    """All 18 committed files derive from the host rows alone; none carries a file digest."""
    # The scripts read the receipt with sed; JSON escapes would hide a row from it.
    unsafe = sorted(path for path in files if not re.fullmatch(r"[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*", path))
    if unsafe:
        raise ValueError(f"Agent Skills paths the clone installers cannot read: {unsafe}")
    result = {}
    for adapter in HOST_ADAPTERS:
        manifest = host_adapter_manifest(adapter.host, files)
        fields = {
            "host": manifest["host"],
            "receipt_name": manifest["inventory"],
            "repo_path": manifest["targets"]["repo"],
            "user_path": manifest["targets"]["user"],
        }
        result[f".{adapter.host}/install.sh"] = _SH.substitute(fields)
        result[f".{adapter.host}/install.ps1"] = _PS1.substitute(fields)
        result[f".{adapter.host}/manifest.json"] = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    return result
